content.command:
pip install msgpack 2>&1 | tail -3 && python3 << 'EOF'
import msgpack

for f in ['/root/.cache/pip/http/a/1/9/5/3/a19537d3cf37c122db841d6fe4cd322bc10d1a558bb00d146b85cb9a',
           '/root/.cache/pip/http/0/4/1/8/c/0418c83b80f7f7bfaec2738bfbbee53d2c1562196c0781702f6eddc8',
           '/root/.cache/pip/http/6/f/5/8/3/6f58315105f89fee1362c31502969537488db877c79a9478a63bd668']:
    with open(f, 'rb') as fh:
        data = fh.read()
    print(f'=== {f.split("/")[-1]} (size: {len(data)}) ===')
    try:
        obj = msgpack.unpackb(data)
        if isinstance(obj, dict):
            print(f'keys: {list(obj.keys())}')
            if 'body' in obj:
                body = obj['body']
                if isinstance(body, bytes):
                    print(f'body len: {len(body)}, first 50: {repr(body[:50])}')
                    # Save body if it looks like a wheel
                    if b'PK' in body[:50]:
                        import tempfile, os
                        with tempfile.NamedTemporaryFile(suffix='.whl', delete=False) as wh:
                            wh.write(body)
                            print(f'SAVED WHEEL to: {wh.name}')
                else:
                    print(f'body type: {type(body)}, content: {body}')
            if 'status' in obj:
                print(f'status: {obj["status"]}')
            if 'headers' in obj:
                print(f'headers: {obj["headers"]}')
    except Exception as e:
        print(f'error: {e}')
    print()
EOF

